  (101574, 101574, 'ml', 'ആവശ്യ നേരത്തെൻ - ആശ്രയം യേശു', 'Aavashya nerathen - aashrayam yeshu'),
  (101575, 101575, 'ml', 'ആവസിക്ക നീയെന്നും വിശുദ്ധ ആത്മാവേ', 'Aavasikka neeyennum vishuddha aathmaave'),
  (101576, 101576, 'ml', 'ആവിയാനവരെ അൻപിൻ', 'Aaviyanavare anpin -Tamil'),
  (101577, 101577, 'ml', 'ആയിരം ആണ്ടുകൾ ഒരുനാൾ പോലെ', 'Aayiram aandukal orunaal pole'),
  (101578, 101578, 'ml', 'ആയിരം ദിവസത്തേക്കാൾ', 'Aayiram divasathekkaal'),
  (101579, 101579, 'ml', 'ആയിരം സൂര്യഗോളങ്ങൾ', 'Aayiram sooryagolangal'),
  (101580, 101580, 'ml', 'ആയിരം സ്തുതികളേക്കാൾ അനുസരണം', 'Aayiram sthuthikalekkaal'),
  (101581, 101581, 'ml', 'ആയിരങ്ങൾ ആഹാരമില്ലാതെ', 'Aayirangal aahaaramillaathe'),
  (101582, 101582, 'ml', 'ആയിരങ്ങൾ വീണാലും പതിനായിരങ്ങൾ', 'Aayirangal veenalum'),
  (101583, 101583, 'ml', 'ആയിരങ്ങളിൽ സുന്ദരൻ വന്ദിതൻ ആരിലുമുന്നതൻ', 'Aayirangalil sundaran vandithan'),
  (101584, 101584, 'ml', 'ആയിരങ്ങളിലും പതിനായിരങ്ങളിലും', 'Aayirangalilum pathinaayira'),
  (101585, 101585, 'ml', 'ആയുസ്സെന്തുള്ളു നമുക്കിങ്ങായുസ്സെന്തുള്ളു', 'Aayussenthullu namukkingayussen'),
  (101586, 101586, 'ml', 'ആയുസ്സു മുഴുവൻ കീർത്തിക്കുവാൻ നാഥാ', 'Aayussu muzhuvan keerthikkuvan'),
  (101587, 101587, 'ml', 'ആഴമാം സ്നേഹം പകർന്നെന്നെ സ്നേഹിക്കും', 'Aazhamaam sneham pakarnnenne'),
  (101588, 101588, 'ml', 'ആഴമാർന്ന സ്നേഹമേ', 'Aazhamaarnna snehame'),
  (101589, 101589, 'ml', 'ആഴമായ് ഇത്രയും സ്നേഹിച്ചീടാൻ', 'Aazhamaay ithrayum snehicchedaan'),
  (101590, 101590, 'ml', 'ആഴമായ് അങ്ങേ സ്നേഹിക്കുവൻ', 'Aazhamay ange snehikkuvan'),
  (101591, 101591, 'ml', 'ആഴങ്ങൾ തേടുന്ന ദൈവം', 'Aazhangal thedunna daivam'),
  (101592, 101592, 'ml', 'ആഴത്തിൽ എന്നോടൊന്നിടപെടണേ', 'Aazhathil ennodonnidapedane'),
  (101593, 101593, 'ml', 'ആഴത്തിൽ നിന്നീശനോടു യാചിക്കുന്നേ ദാസനിപ്പോൾ', 'Aazhathil ninneshanodu yachikkunne'),
  (101594, 101594, 'ml', 'ആഴത്തിൻ മീതേ ദൈവം നടന്നു', 'Aazhathin methe daivam nadannu'),
  (101595, 101595, 'ml', 'ആഴത്തിൽ അങ്ങേ അറിയുവാൻ', 'Aazhatthil ange ariyuvaan'),
  (101596, 101596, 'ml', 'ആഴിമദ്ധ്യത്തില്‍ ആടിയുലയുന്ന', 'Aazhi maddhyathil aadiyulayunna'),
  (101597, 101597, 'ml', 'ആഴിയിൻ ആഴങ്ങളിൽ', 'Aazhiyin aazhngalil'),
  (101598, 101598, 'ml', 'ആഴിയിൻ അലകൾ പോൽ', 'Aazhiyin alakalpol'),
  (101599, 101599, 'ml', 'അബ്ബാ പിതാവേ അങ്ങേ മുന്നിൽ', 'Abba pithave ange munnil');

INSERT INTO song_translations (id, song_id, language_code, title, transliteration) VALUES
  (101600, 101600, 'ml', 'അഭയം അഭയം എന്നേശുവിൽ എന്നും', 'Abhayam abhayam enneshuvil'),
  (101601, 101601, 'ml', 'അഭയം അഭയം തിരുസന്നിധിയിൽ', 'Abhayam abhayam thirusannidhiyil'),
  (101602, 101602, 'ml', 'അഭിഷേകം അഭിഷേകം പരിശുദ്ധാത്മാവിന്റെ', 'Abhishekam abhishekam parishuddha'),
  (101603, 101603, 'ml', 'അഭിഷേകം അഭിഷേകമേ ആത്മാവിൻ', 'Abhishekam abhishekame aathmavin'),
  (101604, 101604, 'ml', 'അഭിഷേകം ചെയ്കെന്നെ പാവനാത്മാവെ', 'Abhishekam cheykenne paavanaathmaave'),
  (101605, 101605, 'ml', 'അഭിഷേകത്തോടെ അധികാരത്തോടെ', 'Abhishekathode adhikarathode'),
  (101606, 101606, 'ml', 'അബ്രഹാം എന്നൊരു വൃദ്ധൻ', 'Abrahaam ennoru vriddhan'),
  (101607, 101607, 'ml', 'അബ്രഹാമിൻ ദൈവം', 'Abrahamin daivam'),
  (101608, 101608, 'ml', 'അബ്രഹാമിൻ ദൈവം എന്റെ ദൈവം', 'Abrahamin daivam ente daivam'),
  (101609, 101609, 'ml', 'അടഞ്ഞ വാതിലും വറ്റിയ ഉറവയും', 'Adanja vaathilum vatiya uravayum'),
  (101610, 101610, 'ml', 'അടവിതരുക്കളിനിടയിൽ ഒരു നാരകമെന്നവണ്ണം', 'Adavi tharukkalinidayil oru naarakam'),
  (101611, 101611, 'ml', 'അടയാളങ്ങൾ കാണുന്നുണ്ട്‌ ഒരുങ്ങിട്ടുണ്ടോ', 'Adayaalngal kaanunnunde orungittundo'),
  (101612, 101612, 'ml', 'അദ്ധ്വാനിക്കുന്നവരേ ഭാരം ചുമക്കുന്നോരേ', 'Addhvanikkunnavare bhaaram'),
  (101613, 101613, 'ml', 'അധിപതിയേ അങ്ങേസ്തുതിച്ചിടുന്നേൻ', 'Adhipathiye ange sthuthichidunnen'),
  (101614, 101614, 'ml', 'അടിപിടി വേണ്ട ഇടിപിടി', 'Adipidi venda idipidi venda'),
  (101615, 101615, 'ml', 'അടിയൻ ഇതാ അപ്പനെ അടിയൻ', 'Adiyan ithaa appane adiyan'),
  (101616, 101616, 'ml', 'അടിയനിതാ എന്നെ അയക്കണെമെ', 'Adiyanithaa enne ayakkaneme'),
  (101617, 101617, 'ml', 'അടിയന്റെ ആശ അടിയന്റെ വാഞ്ച', 'Adiyante aasha adiyante vaanjcha'),
  (101618, 101618, 'ml', 'അദൃശ്യകരങ്ങളാൽ കരുതിടും ദൈവം', 'Adrshya karangalaal karuthidum daivam'),
  (101619, 101619, 'ml', 'അടുത്തിടുന്നു നാം അടുത്തിടുന്നു പ്രാണ', 'Aduthidunnu naam aduthidunnu praana'),
  (101620, 101620, 'ml', 'അഗാതമാം ആഴങ്ങളിൽ ഞാൻ', 'Agathamam aazhangalil njaan'),
  (101621, 101621, 'ml', 'അഗ്നിയാൽ എന്നെ നിറയ്ക്കും', 'Agniyaal enne niraykkum'),
  (101622, 101622, 'ml', 'അഗ്നിയുടെ അഭിഷേകം പകരണമെ', 'Agniyude abhishekam pakaraname'),
  (101623, 101623, 'ml', 'അകലാത്ത സ്നേഹിതൻ', 'Akalaatha snehithan'),
  (101624, 101624, 'ml', 'അഖിലാണ്ഡത്തിന്നുടയവനാം ദൈവം', 'Akhilandathin udayavanaam daivam'),
  (101625, 101625, 'ml', 'അഖിലാണ്ഡത്തിനുടയനാം നാഥാ', 'Akilandathinudayanam natha'),
  (101626, 101626, 'ml', 'അക്കരയ്ക്കുയാത്രചെയ്യും സീയോൻ സഞ്ചാരി', 'Akkarakku yaathra cheiyyum seyon'),
  (101627, 101627, 'ml', 'അക്കരെ നാട്ടിലെ നിത്യ ഭവനം', 'Akkare nattile nithya bhavanam'),
  (101628, 101628, 'ml', 'അക്കരെ നാട്ടിലെൻ വാസമേകിടാൻ', 'Akkare nattilen vaasamekidan'),
  (101629, 101629, 'ml', 'അഴൈത്തവരെ  അഴൈത്തവരെ', 'Alaiththavarae alaiththavarae-Tamil'),
  (101630, 101630, 'ml', 'അളന്നു തരുന്ന ലോകം അതിരിടുന്ന ലോകം', 'Alannu tharunna lokam athiridunna lokam'),
  (101631, 101631, 'ml', 'അളന്നു തൂക്കി തരുന്നവനല്ലയെൻ ദൈവം', 'Alannu thukki tharunnavanallayen daivam'),
  (101632, 101632, 'ml', 'അളവില്ലാ ദാനങ്ങൾ നൽകുന്നോനെ', 'Alavilla danangal nalkunnone'),
  (101633, 101633, 'ml', 'അളവില്ല സ്നേഹം യേശുവിൻ സ്നേഹം മാത്രം', 'Alavilla sneham yeshuvin sneham'),
  (101634, 101634, 'ml', 'അല്ലലില്ലാ നാടുണ്ട് സ്വർഗ്ഗനാടുണ്ട്', 'Allalillaa nadunde swargga nadunde'),
  (101635, 101635, 'ml', 'അല്ലലില്ലല്ലോ എനിക്കല്ലലില്ലല്ലോ', 'Allalillallo enikkallalillallo'),
  (101636, 101636, 'ml', 'അല്പകാല വാസം തീരാറായി', 'Alpakaala vaasam theeraaraayi'),
  (101637, 101637, 'ml', 'അല്പകാലം മാത്രം ഈ ഭൂവിലെ വാസം', 'Alpakaalam maathram ie bhoovile vasam'),
  (101638, 101638, 'ml', 'അൽപ്പം ദൂരം മാത്രം ഈ യാത്ര തീരുവാൻ', 'Alppam duram mathram ie yathra'),
  (101639, 101639, 'ml', 'അംബ യെരുശലേം അംബരിൻ കാഴ്ചയിൽ', 'Amba yerushalem ambarin'),
  (101640, 101640, 'ml', 'അമ്മ തൻ കുഞ്ഞുങ്ങളെ മറന്നു പോകുമോ', 'Amma than kunjungale marannu'),
  (101641, 101641, 'ml', 'അമ്മക്കിളിയും കുഞ്ഞിക്കിളികളും', 'Ammakiliyum kunjikkilikalum'),
  (101642, 101642, 'ml', 'അമ്മതൻ ഉദരത്തിൽ - നന്ദി പറഞ്ഞിടുവാൻ', 'Ammathan udaratthil - nandi paranjiduvaan'),
  (101643, 101643, 'ml', 'അമ്മതൻ ഉദരത്തിൽ ഉരുവാകും മുൻപേ', 'Ammathan udaratthil uruvaakum munpe'),
  (101644, 101644, 'ml', 'അനാദിനാഥനേശുവെൻ ധനം', 'Anaadi nathhan yeshuven dhanam'),
  (101645, 101645, 'ml', 'അനാദി സ്നേഹത്താൽ എന്നെ സ്നേഹിച്ച നാഥാ', 'Anaadi snehathaal enne snehicha'),
  (101646, 101646, 'ml', 'അനാദി സ്നേഹത്താൽ എന്നെ സ്നേഹിച്ച', 'Anaadi snehathaal enne snehicha daivam'),
  (101647, 101647, 'ml', 'അനാദി സ്നേഹത്താൽ എന്നൈ', 'Anaadi snehathal enne -Tamil'),
  (101648, 101648, 'ml', 'അനാഥനായ് ഞാൻ വിടുകയില്ല', 'Anaathhanaay njaan vidukayilla'),
  (101649, 101649, 'ml', 'അനാഥരോ പ്രിയരേ', 'Anaathharo priyare'),
  (101650, 101650, 'ml', 'അനാദിയാം മഹദ് വചനം', 'Anadiyam mahad vachanam'),
  (101651, 101651, 'ml', 'അനന്ത സ്നേഹമേ അവർണ്യ രൂപനേ', 'Anantha snehame avarnnya rupane'),
  (101652, 101652, 'ml', 'അനന്ത വിഹായസ്സിൽ ദൂരെ - നിത്യവിശ്രാമം', 'Anantha vihayassil doore - nithya vishraamam'),
  (101653, 101653, 'ml', 'അനശ്വര ദേവാ ആശ്വസിപ്പിക്കെന്നെ', 'Anashvara devaa aashvasippikkenne'),
  (101654, 101654, 'ml', 'അന്ധകാരമേറും ലോകയാത്രയിൽ', 'Andhakaramerum lokayaathrayil'),
  (101655, 101655, 'ml', 'അന്ധകാരത്താലെല്ലാ കണ്ണും മങ്ങുമ്പോൾ മങ്ങിടാത്ത', 'Andhakarathalella kannum mangumpol'),
  (101656, 101656, 'ml', 'അനേകരും തെറ്റി ഒഴിഞ്ഞിടും', 'Anekarum theti ozhinjidum'),
  (101657, 101657, 'ml', 'അനേകരും തെറ്റി ഒഴിഞ്ഞിടും', 'Anekarum thetti ozhinjidum'),
  (101658, 101658, 'ml', 'അങ്ങകലെ ഞാൻ - പ്രിയൻ ഇമ്പസ്വരം', 'Angakale njaan - priyan impasvaram'),
  (101659, 101659, 'ml', 'അങ്ങറിയാതെ എന്റെ ജീവിതത്തിൽ', 'Angariyaathe ente jeevithatthil'),
  (101660, 101660, 'ml', 'അങ്ങയെ ഞാൻ വന്ദിക്കുന്നെ', 'Angaye njaan vandikkunne'),
  (101661, 101661, 'ml', 'അങ്ങേ ആരാധിക്കുന്നേ', 'Ange aaradhikkunne'),
  (101662, 101662, 'ml', 'അങ്ങെ ആരാധിക്കുന്നതാണെൻ ആശ', 'Ange aaradikunnathanen'),
  (101663, 101663, 'ml', 'അങ്ങേ ഹിതം പോലെന്നെ', 'Ange hitham polenne'),
  (101664, 101664, 'ml', 'അങ്ങെ മാത്രം നോക്കുന്നു', 'Ange maathram nokkunnu'),
  (101665, 101665, 'ml', 'അങ്ങെ മാത്രം സേവിക്കുവാൻ', 'Ange maathram sevikkuvaan'),
  (101666, 101666, 'ml', 'അങ്ങേപിരിഞ്ഞൊരു ജീവിതം വേണ്ടാ', 'Ange pirinjoru jeevitham vendaa'),
  (101667, 101667, 'ml', 'അങ്ങേ പോലെ ആകുവാൻ', 'Ange pole aakuvan'),
  (101668, 101668, 'ml', 'അങ്ങെ പോലെ ആയിത്തീരാൻ', 'Ange pole aayitheeraan'),
  (101669, 101669, 'ml', 'അങ്ങേക്കാൾ വേറെ ഒന്നിനെയും', 'Angekkal vere onnineyum'),
  (101670, 101670, 'ml', 'അങ്ങേക്കാൾ വേറെ ഒന്നിനേയും സ്നേഹിക്കില്ലാ', 'Angekkal vere onnineyum snehikkilla - medley'),
  (101671, 101671, 'ml', 'അങ്ങേകും ദാനങ്ങളോർത്താൽ', 'Angekum danangal (nin sannidhyam)'),
  (101672, 101672, 'ml', 'അങ്ങെന്നെ ജീവിപ്പിക്കും', 'Angenne jeevippikkum'),
  (101673, 101673, 'ml', 'അങ്ങെന്റെ പാറയാം', 'Angente paarayaam'),
  (101674, 101674, 'ml', 'അങ്ങേപൊലെ ആരുമില്ല', 'Angepole aarumilla-Tumsa koi nahi'),
  (101675, 101675, 'ml', 'അങ്ങെപ്പോലെൻ ദൈവമെ ആരുള്ളീ ലോകെ', 'Angepolen daivame aarullee loke'),
  (101676, 101676, 'ml', 'അങ്ങിവിടെ ആവസിക്കുന്നു', 'Angivide aavasikkunnu (waymaker)'),
  (101677, 101677, 'ml', 'അണിഅണിയായി പടയണിയായ്', 'Anianiyai pdayaniyai'),
