  (102300, 102300, 'ml', 'എൻ പ്രിയനെന്തു മനോഹരനാം തൻപാദമെന്നു', 'En priyanenthu manoharanam thanpatha'),
  (102301, 102301, 'ml', 'എൻ പ്രിയനെ​പ്പോൽ സുന്ദരനായ് ആരെയും', 'En priyaneppol sundaranaay aareyum njaan'),
  (102302, 102302, 'ml', 'എൻ പ്രിയന്റെ വരവേറ്റം അടുത്തു പോയി', 'En priyante varavetam aduthu poyi'),
  (102303, 102303, 'ml', 'എൻ രക്ഷകാ എൻ ദൈവമേ നിന്നിലായ നാൾ', 'En rakshaka en divame ninnilayanal'),
  (102304, 102304, 'ml', 'എൻ രക്ഷക എൻ യേശുവെ', 'En rakshaka en yeshuve'),
  (102305, 102305, 'ml', 'എൻ രക്ഷകനാമെശുവേ എന്നെ ദയയോടു', 'En rakshakanaam yeshuve enne daya'),
  (102306, 102306, 'ml', 'എൻ രക്ഷകനേശുനാഥനെന്നും ജീവിക്കുന്നു', 'En rakshakaneshu nathaninnum'),
  (102307, 102307, 'ml', 'എൻ രക്ഷയാം യഹോവ', 'En rakshayaam yahova'),
  (102308, 102308, 'ml', 'എൻ സങ്കടങ്ങൾ സകലതും തീർന്നുപോയി സംഹാര', 'En sankadangal sakalavum theernnupoyi'),
  (102309, 102309, 'ml', 'എൻ ശരണം നീയേ എൻ ജീവനും നീ', 'En sharanam neeyae en jeevanum nee'),
  (102310, 102310, 'ml', 'എൻ സ്നേഹിതാ എൻ ദൈവമേ', 'En snehithaa en daivame'),
  (102311, 102311, 'ml', 'എൻ ഉള്ളം അറിയുന്ന നാഥാ', 'En ullam ariyunna naathaa'),
  (102312, 102312, 'ml', 'എൻ ഉയിരാനെ യേശു എൻ ഉയിരോട് കലന്തു', 'En uyirana yeshu -Tamil'),
  (102313, 102313, 'ml', 'എൻ യഹോവായേ പാപിക്കാശ്രയം', 'En yahovaaye papikkashrayam'),
  (102314, 102314, 'ml', 'എൻ യേശു എൻ പ്രിയൻ എനിക്കുള്ളോൻ നീ', 'En yeshu en priyan enikkullon'),
  (102315, 102315, 'ml', 'എൻയേശു എനിക്കായ് കരുതിടുമ്പോൾ', 'En yeshu enikkay karuthidumpol'),
  (102316, 102316, 'ml', 'എൻ യേശു നാഥന്റെ പാദത്തിങ്കൽ ഞാൻ', 'En yeshu nathhante padathingkal njaan'),
  (102317, 102317, 'ml', 'എൻ യേശു രക്ഷകൻഎൻ നല്ല ഇടയൻ', 'En yeshu rakshakan en nalla idayan'),
  (102318, 102318, 'ml', 'എൻ യേശു രക്ഷകനേ കർത്താ', 'En yeshu rakshakane kartthaa'),
  (102319, 102319, 'ml', 'എൻ യേശുവല്ലാതില്ലെനിക്കൊരാശ്രയം', 'En yeshuvallaa thillenikkorashrayam'),
  (102320, 102320, 'ml', 'എൻ യേശുവേ എൻ ജീവനേ എന്നാശ നീ', 'En yeshuve en jeevane ennasha ne'),
  (102321, 102321, 'ml', 'എൻ യേശുവേ എൻ പ്രിയനെ', 'En yeshuve en priyane'),
  (102322, 102322, 'ml', 'എൻ യേശുവേ നടത്തിടണേ നിൻഹിതം', 'En yeshuve nadathidane nin'),
  (102323, 102323, 'ml', 'എൻ യേശുവേ പോൽ ഉന്നതൻ ആരുള്ളു', 'En yeshuve pol unnathan arullu'),
  (102324, 102324, 'ml', 'എൻ യേശുവേ രക്ഷകാ നല്ല സ്നേഹിതൻ നീ', 'En yeshuve rashaka nalla snehithan'),
  (102325, 102325, 'ml', 'എന്നേശുവിൻ സന്നിധിയിൽ എന്നും ഗീതങ്ങൾ', 'En yeshuvin sannidhiyil ennum geethangal'),
  (102326, 102326, 'ml', 'എൻ യേശുവുണ്ട് കൂടെ തെല്ലും', 'En yeshuvunde koode'),
  (102327, 102327, 'ml', 'എങ്കലുക്കുള്ളെ വാസം സെയ്യും ആവിയാനവരെ', 'Engalukkullai vaasam seyyum-Tamil'),
  (102328, 102328, 'ml', 'എങ്ങനെ മറന്നിടും എൻ പ്രിയൻ', 'Engane marannidum en priyan'),
  (102329, 102329, 'ml', 'എങ്കിലും എന്റെ എൻ മഹാപാപം', 'Engilum ente en mahaapaapam'),
  (102330, 102330, 'ml', 'എങ്ങോ ചുമന്നു പോകുന്നു! കുരിശുമരം', 'Engo chumannu pokunnu'),
  (102331, 102331, 'ml', 'എങ്ങും പുകഴ്ത്തുവിൻ സുവിശേഷം ഹാ', 'Engum pukazthuvin suvishesham'),
  (102332, 102332, 'ml', 'എനിക്കല്ല ഞാൻ ക്രിസ്തുവിനത്രെ അവന്നായിതാ', 'Enikkalla njaan kristhuvinathre'),
  (102333, 102333, 'ml', 'എനിക്കാനന്ദമുണ്ട് ആനന്ദമുണ്ട്', 'Enikkanandamunde aanandamunde'),
  (102334, 102334, 'ml', 'എനിക്കായ് ഭൂവിൽ വന്ന് ജീവൻ തന്നു', 'Enikkay bhuvil vannu jeevan'),
  (102335, 102335, 'ml', 'എനിക്കായ് കരുതാമെന്നുരച്ചവനെ എനിക്കൊട്ടും', 'Enikkay karutham ennurachavane'),
  (102336, 102336, 'ml', 'എനിക്കായ് കരുതും, എന്നെ വഴി നടത്തും', 'Enikkay karuthum enne vazhi'),
  (102337, 102337, 'ml', 'എനിക്കായ് കരുതുന്നവൻ', 'Enikkay karuthunnavan (pareeksha ente)'),
  (102338, 102338, 'ml', 'എനിക്കായ് കുരിശിൽ മരിച്ചു', 'Enikkay kurishil maricchu'),
  (102339, 102339, 'ml', 'എനിക്കായ് മരിച്ച യേശുനാഥാ', 'Enikkay mariccha yeshu nathhaa'),
  (102340, 102340, 'ml', 'എനിക്കായ് മരിച്ചവൻ മനുഷ്യനല്ല', 'Enikkay maricchavan manushyanalla'),
  (102341, 102341, 'ml', 'എനിക്കായ് മരിച്ചവനെ', 'Enikkay marichavane'),
  (102342, 102342, 'ml', 'എനിക്കായ് മരിച്ചവനെ എന്നെ നന്നായി', 'Enikkay marichavane enne nannaayi'),
  (102343, 102343, 'ml', 'എനിക്കായി മരിച്ചവനെ മരണത്തെ', 'Enikkay marichavane maranathe'),
  (102344, 102344, 'ml', 'എനിക്കായി മരിച്ചുയിർത്ത എന്റെ', 'Enikkay marichuyirtha ente'),
  (102345, 102345, 'ml', 'എനിക്കായ് നല്ലൊരു തുണയായ് വന്നു', 'Enikkay nalloru thunayaay vannu'),
  (102346, 102346, 'ml', 'എനിക്കായ് നീ മരിച്ചു എൻ', 'Enikkay nee marichu en'),
  (102347, 102347, 'ml', 'എനിക്കായ് സ്വപുത്രനെ തന്നവൻ', 'Enikkay svaputhrane thannavan'),
  (102348, 102348, 'ml', 'എനിക്കായ് തകർന്നതല്ലേ', 'Enikkay thakarnnathalle'),
  (102349, 102349, 'ml', 'എനിക്കായ് തുറന്നോരുറവ', 'Enikkay thurannorurava'),
  (102350, 102350, 'ml', 'എനിക്കായൊരു ഭവനം ഉയരെ', 'Enikkayoru bhavanam uyare anguyare'),
  (102351, 102351, 'ml', 'എനിക്കായൊരു സമ്പത്ത് ഉയരെ', 'Enikkayoru sampathe uyare'),
  (102352, 102352, 'ml', 'എനിക്കായൊരുത്തമ സമ്പത്ത് സ്വർഗ്ഗ', 'Enikkayoruthama sampathe'),
  (102353, 102353, 'ml', 'എനിക്ക് വേണ്ടി കരുതി ദൈവം', 'Enikke vendi karuthi daivam'),
  (102354, 102354, 'ml', 'എനിക്കെന്നും യേശുവുണ്ട്', 'Enikkennum yeshuvunde'),
  (102355, 102355, 'ml', 'എനിക്കെന്റെ ജീവിതത്തിൽ', 'Enikkente Jeevithathil'),
  (102356, 102356, 'ml', 'എനിക്കെന്റെ ആശ്രയം യേശുവത്രേ', 'Enikkente aashrayam yeshuvathre'),
  (102357, 102357, 'ml', 'എനിക്കെന്റെ കർത്താവുണ്ടല്ലോ', 'Enikkente karthavundallo'),
  (102358, 102358, 'ml', 'എനിക്കെന്റെ യേശു മാത്രം അവൻ മതിയായവൻ', 'Enikkente yeshu maathram avan'),
  (102359, 102359, 'ml', 'എനിക്കെന്റെ യേശുവിനെ കണ്ടാൽമതി', 'Enikkente yeshuvine kandaal mathi'),
  (102360, 102360, 'ml', 'എനിക്കേശുവുണ്ടീ മരുവിൽ എല്ലാ', 'Enikkeshuvundee maruvil'),
  (102361, 102361, 'ml', 'എനിക്കേതു നേരത്തിലും', 'Enikkethu nerathilum'),
  (102362, 102362, 'ml', 'എനിക്കിനി ജീവൻ ക്രിസ്തുവത്രേ മരിക്കിലുമെനിക്കതു', 'Enikkini jeevan kristhuvethre'),
  (102363, 102363, 'ml', 'എനിക്കിനിയുമെല്ലാമായ് നീമതിയൂഴിയിൽ', 'Enikkiniyum ellaamaay nee mathiyuzhiyil'),
  (102364, 102364, 'ml', 'എനിക്കിനിയും എല്ലാമായ് നീ മതി ഊഴിയിൽ', 'Enikkiniyum ellamai ne mathi uziyil'),
  (102365, 102365, 'ml', 'എനിക്കൊന്നിലും ഭാരമില്ല', 'Enikkonnilum bhaaramilla'),
  (102366, 102366, 'ml', 'എനിക്കൊരമ്മയെപ്പോൽ ആശ്രയിപ്പാനും', 'Enikkorammayeppol aashrayippaanum'),
  (102367, 102367, 'ml', 'എനിക്കൊരു ദൈവമുണ്ടു പ്രാർത്ഥന കേൾക്കാൻ', 'Enikkoru daivamunde prarthhana'),
  (102368, 102368, 'ml', 'എനിക്കൊരു ദൈവമുണ്ട് സ്വർഗ്ഗത്തിൽ', 'Enikkoru daivamunde swargathil'),
  (102369, 102369, 'ml', 'എനിക്കൊരു തുണ നീയെ എൻ പ്രിയനെ', 'Enikkoru thuna neeye en priyane'),
  (102370, 102370, 'ml', 'എനിക്കൊരു ഉത്തമഗീതം', 'Enikkoru uthama geetham'),
  (102371, 102371, 'ml', 'എനിക്കൊത്താശ വരും പർവ്വതം കർത്താവേ നീ', 'Enikkothasha varum parvatham'),
  (102372, 102372, 'ml', 'എനിക്കു നിൻ കൃപ മതിയേ പ്രിയനേ', 'Enikku nin krupa mathiye priyane'),
  (102373, 102373, 'ml', 'എനിക്കു തണലും താങ്ങുമായെൻ യേശുനായകാ', 'Enikku thanalum thangumayen'),
  (102374, 102374, 'ml', 'എനിക്കു വേറില്ലാശ ഒന്നുമെൻ പ്രിയനെ', 'Enikku verrillaasha onnumen'),
  (102375, 102375, 'ml', 'എനിക്കുണ്ടൊരു പുത്തൻ പാട്ടുപാടാൻ', 'Enikkundoru puthan paattupaadaan'),
  (102376, 102376, 'ml', 'എനിക്കുണ്ടൊരു ഉത്തമ സ്നേഹിതൻ', 'Enikkundoru uthama snehithan'),
  (102377, 102377, 'ml', 'എന്നാൽ യേശു വന്നിടും', 'Ennaal yeshu vannidum'),
  (102378, 102378, 'ml', 'എന്നാശ അതൊന്നു മാത്രമേ', 'Ennaasha athonnu maathrame'),
  (102379, 102379, 'ml', 'എന്നാശ എന്നുമെന്റെ രക്ഷിതാവിലാകയാൽ', 'Ennaasha ennumente rakshithavilakayal'),
  (102380, 102380, 'ml', 'എന്നാശ്രയം എന്നേശുവിൽ മാത്രം', 'Ennaashrayam enneshuvil mathram'),
  (102381, 102381, 'ml', 'എന്നാശ്രയം യേശുവിലാം നിത്യ', 'Ennaashrayam yeshuvilaam nithya'),
  (102382, 102382, 'ml', 'എന്നാശ്രയമെൻ യേശുവിലാകയാൽ', 'Ennaashrayamen yeshuvilaakayaal'),
  (102383, 102383, 'ml', 'എന്നാത്മ നാഥനാം എൻ പ്രിയൻ യേശുവേ', 'Ennaathma naadhanaam en priyan'),
  (102384, 102384, 'ml', 'എന്നാത്മപ്രീയൻ സ്വർഗ്ഗസീയോനിൽ', 'Ennaathma priyan swargga seeyonil'),
  (102385, 102385, 'ml', 'എന്നാത്മനാഥ എന്നെശുവേ', 'Ennaathmanatha enneshuve'),
  (102386, 102386, 'ml', 'എന്നാത്മാവേ വാഴ്ത്തുക നീ', 'Ennaathmave vazhthuka nee'),
  (102387, 102387, 'ml', 'എന്നാലംബം യേശുവിൽ അത്രേ', 'Ennalambam yeshuvil athre'),
  (102388, 102388, 'ml', 'എന്നാളും ആശ്രയമാം കർത്താവിനെ', 'Ennalum aashrayamam karthavine'),
  (102389, 102389, 'ml', 'എന്നാളും സ്തുതിച്ചീടുമെ ഞാൻ', 'Ennalum sthuthichedume njaan'),
  (102390, 102390, 'ml', 'എന്നാളും സ്തുതിക്കണം നാം നാഥനെ എന്നാളും', 'Ennalum sthuthikkanam naam nathhane'),
  (102391, 102391, 'ml', 'എണ്ണമില്ലാ നന്മകൾ എന്നിൽ', 'Ennamilla nanmakal ennil'),
  (102392, 102392, 'ml', 'എണ്ണമില്ലാ നന്മകൾ മാത്രം', 'Ennamillaa nanmakal maathram'),
  (102393, 102393, 'ml', 'എണ്ണമില്ലാതുള്ള നന്മകൾ തന്നെന്നെ', 'Ennamillathulla nanmakal thannenne'),
  (102394, 102394, 'ml', 'എന്നന്തരംഗവും എൻ ജീവനും ജീവനുള്ള', 'Ennantharagavum en jeevanum'),
  (102395, 102395, 'ml', 'എന്നാണുദയം ഇരുളാണുലകിൽ', 'Ennanudayam irulaanulakil neethi'),
  (102396, 102396, 'ml', 'എന്നപ്പനിഷ്ട പുത്രനാക്കുവാൻ', 'Ennappanishta puthranakkuvan'),
  (102397, 102397, 'ml', 'എന്നതിക്രമം നിമിത്തം മുറിവേറ്റവനേ', 'Ennathikramam nimiththam murivettavane'),
  (102398, 102398, 'ml', 'എന്നവിടെ വന്നു ചേരും ഞാൻ മമ കാന്ത, നിന്നെ', 'Ennavide vannu cherum njaan mama'),
  (102399, 102399, 'ml', 'എന്നെ അൻപോടു സ്നേഹിപ്പാൻ', 'Enne anpodu snehippan');

INSERT INTO song_translations (id, song_id, language_code, title, transliteration) VALUES
  (102400, 102400, 'ml', 'എന്നെ അനുദിനം നടത്തുന്ന കർത്തനവൻ', 'Enne anudinam nadathunna karthanavan'),
  (102401, 102401, 'ml', 'എന്നെ അറിയാൻ എന്നെ നടത്താൻ എല്ലാ', 'Enne ariyan enne nadathan ella nalilum'),
  (102402, 102402, 'ml', 'എന്നെ അറിയുന്ന - പിരിയാത്ത സ്നേഹിതൻ', 'Enne ariyunna - piriyatha snehithan'),
