  (126173, 105127, 'verse1', 'തറച്ചാരവൻ മരിച്ചാനുയിർ ധരിച്ചാൻ മാനുവേൽ', NULL),
  (126174, 105127, 'verse2', '1 താതസവിധമതിൽ താനേ സമർപ്പിച്ചതാൽ
